{
  "goal": "Analyze quarterly sales CSV files, detect and repair data-quality issues, compute quarterly statistics, merge results, run a quality review, and generate a consolidated Markdown report with an evidence log.",
  "steps": [
    {
      "kind": "foreach",
      "name": "process_files",
      "over": "inputs",
      "output": {
        "name": "all_file_reports",
        "typeName": "List<Record>"
      },
      "body": [
        {
          "kind": "primitive",
          "name": "detect_issues",
          "capability": "execute_python",
          "code": "import pandas as pd\ndf = pd.read_csv(\"${item}\")\nissues = []\nexpected_cols = [\"date\", \"product\", \"quantity\", \"price\", \"total\"]\nif list(df.columns) != expected_cols:\n    issues.append(f\"Schema drift: expected {expected_cols}, got {list(df.columns)}\")\nif not pd.api.types.is_numeric_dtype(df[\"quantity\"]):\n    issues.append(\"Type error: quantity is not numeric\")\nif not pd.api.types.is_numeric_dtype(df[\"price\"]):\n    issues.append(\"Type error: price is not numeric\")\nmissing = df.isnull().sum()\nif missing.any():\n    issues.append(f\"Missing values: {missing.to_dict()}\")\ndups = df.duplicated().sum()\nif dups > 0:\n    issues.append(f\"Duplicates: {dups} rows\")\nQ1 = df[\"price\"].quantile(0.25)\nQ3 = df[\"price\"].quantile(0.75)\nIQR = Q3 - Q1\noutliers = ((df[\"price\"] < (Q1 - 1.5 * IQR)) | (df[\"price\"] > (Q3 + 1.5 * IQR))).sum()\nif outliers > 0:\n    issues.append(f\"Outliers in price: {outliers}\")\nenv[\"detected_issues\"] = {\"issues\": issues, \"dataframe\": df}",
          "output": {
            "name": "detected_issues",
            "typeName": "Record",
            "fields": [
              {"name": "issues", "typeName": "List<String>"},
              {"name": "dataframe", "typeName": "Any"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "repair_issues",
          "capability": "execute_python",
          "inputBindings": [
            {"param": "detected_issues", "source": "detect_issues", "binding": "detected_issues"}
          ],
          "code": "import pandas as pd\ndata = detected_issues[\"dataframe\"]\nrepairs = []\nif not pd.api.types.is_numeric_dtype(data[\"quantity\"]):\n    data[\"quantity\"] = pd.to_numeric(data[\"quantity\"], errors=\"coerce\")\n    repairs.append(\"Converted quantity to numeric\")\nif not pd.api.types.is_numeric_dtype(data[\"price\"]):\n    data[\"price\"] = pd.to_numeric(data[\"price\"], errors=\"coerce\")\n    repairs.append(\"Converted price to numeric\")\nif data.isnull().sum().any():\n    data = data.fillna({\"quantity\": 0, \"price\": 0, \"total\": 0})\n    repairs.append(\"Filled missing numeric values with 0\")\nif data.duplicated().sum() > 0:\n    data = data.drop_duplicates()\n    repairs.append(\"Dropped duplicate rows\")\nQ1 = data[\"price\"].quantile(0.25)\nQ3 = data[\"price\"].quantile(0.75)\nIQR = Q3 - Q1\nlower = Q1 - 1.5 * IQR\nupper = Q3 + 1.5 * IQR\noutliers = (data[\"price\"] < lower) | (data[\"price\"] > upper)\nif outliers.any():\n    data[\"price\"] = data[\"price\"].clip(lower=lower, upper=upper)\n    repairs.append(\"Capped outliers in price\")\nenv[\"repaired_data\"] = {\"dataframe\": data, \"repairs_applied\": repairs}",
          "output": {
            "name": "repaired_data",
            "typeName": "Record",
            "fields": [
              {"name": "dataframe", "typeName": "Any"},
              {"name": "repairs_applied", "typeName": "List<String>"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "revalidate",
          "capability": "execute_python",
          "inputBindings": [
            {"param": "repaired_data", "source": "repair_issues", "binding": "repaired_data"}
          ],
          "code": "import pandas as pd\ndf = repaired_data[\"dataframe\"]\nremaining = []\nif df.isnull().sum().any():\n    remaining.append(\"Missing values remain\")\nif df.duplicated().sum() > 0:\n    remaining.append(\"Duplicates remain\")\nif not pd.api.types.is_numeric_dtype(df[\"quantity\"]):\n    remaining.append(\"Type error in quantity remains\")\nif not pd.api.types.is_numeric_dtype(df[\"price\"]):\n    remaining.append(\"Type error in price remains\")\nenv[\"validation_report\"] = {\"is_valid\": len(remaining) == 0, \"remaining_issues\": remaining}",
          "output": {
            "name": "validation_report",
            "typeName": "Record",
            "fields": [
              {"name": "is_valid", "typeName": "Boolean"},
              {"name": "remaining_issues", "typeName": "List<String>"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "compute_statistics",
          "capability": "execute_python",
          "inputBindings": [
            {"param": "repaired_data", "source": "repair_issues", "binding": "repaired_data"}
          ],
          "code": "import pandas as pd\ndf = repaired_data[\"dataframe\"]\nstats = {\n    \"total_sales\": float(df[\"total\"].sum()) if \"total\" in df.columns else float((df[\"quantity\"] * df[\"price\"]).sum()),\n    \"average_sales\": float(df[\"total\"].mean()) if \"total\" in df.columns else float((df[\"quantity\"] * df[\"price\"]).mean()),\n    \"min_sales\": float(df[\"total\"].min()) if \"total\" in df.columns else float((df[\"quantity\"] * df[\"price\"]).min()),\n    \"max_sales\": float(df[\"total\"].max()) if \"total\" in df.columns else float((df[\"quantity\"] * df[\"price\"]).max()),\n    \"row_count\": int(len(df))\n}\nenv[\"quarterly_stats\"] = stats",
          "output": {
            "name": "quarterly_stats",
            "typeName": "Record",
            "fields": [
              {"name": "total_sales", "typeName": "Number"},
              {"name": "average_sales", "typeName": "Number"},
              {"name": "min_sales", "typeName": "Number"},
              {"name": "max_sales", "typeName": "Number"},
              {"name": "row_count", "typeName": "Integer"}
            ]
          }
        },
        {
          "kind": "primitive",
          "name": "compile_file_report",
          "capability": "execute_python",
          "inputBindings": [
            {"param": "stats", "source": "compute_statistics", "binding": "quarterly_stats"},
            {"param": "validation", "source": "revalidate", "binding": "validation_report"},
            {"param": "issues", "source": "detect_issues", "binding": "detected_issues"}
          ],
          "code": "report = {\n    \"stats\": stats,\n    \"validation\": validation,\n    \"issues\": issues[\"issues\"]\n}\nenv[\"file_report\"] = report",
          "output": {
            "name": "file_report",
            "typeName": "Record",
            "fields": [
              {"name": "stats", "typeName": "Record"},
              {"name": "validation", "typeName": "Record"},
              {"name": "issues", "typeName": "List<String>"}
            ]
          }
        }
      ]
    },
    {
      "kind": "primitive",
      "name": "merge_results",
      "capability": "execute_python",
      "inputBindings": [
        {"param": "file_reports", "source": "process_files", "binding": "all_file_reports"}
      ],
      "code": "all_stats = [r[\"stats\"] for r in file_reports]\nall_issues = []\nfor r in file_reports:\n    all_issues.extend(r[\"issues\"])\n    all_issues.extend(r[\"validation\"][\"remaining_issues\"])\naggregated = {\n    \"total_sales\": sum(s[\"total_sales\"] for s in all_stats),\n    \"average_sales\": sum(s[\"average_sales\"] for s in all_stats) / len(all_stats),\n    \"min_sales\": min(s[\"min_sales\"] for s in all_stats),\n    \"max_sales\": max(s[\"max_sales\"] for s in all_stats),\n    \"total_rows\": sum(s[\"row_count\"] for s in all_stats),\n    \"quarters_processed\": len(all_stats)\n}\nenv[\"merged_results\"] = {\"aggregated_stats\": aggregated, \"all_issues\": all_issues}",
      "output": {
        "name": "merged_results",
        "typeName": "Record",
        "fields": [
          {"name": "aggregated_stats", "typeName": "Record"},
          {"name": "all_issues", "typeName": "List<String>"}
        ]
      }
    },
    {
      "kind": "primitive",
      "name": "quality_review",
      "capability": "execute_python",
      "inputBindings": [
        {"param": "merged_results", "source": "merge_results", "binding": "merged_results"}
      ],
      "code": "issues = merged_results[\"all_issues\"]\nreview_summary = f\"Found {len(issues)} issues across all quarters.\"\nrecommendations = []\nif any(\"Schema drift\" in i for i in issues):\n    recommendations.append(\"Standardize CSV schemas.\")\nif any(\"Missing values\" in i for i in issues):\n    recommendations.append(\"Implement data collection checks for missing fields.\")\nif any(\"Outliers\" in i for i in issues):\n    recommendations.append(\"Review outlier capping thresholds.\")\nenv[\"quality_review_report\"] = {\"review_summary\": review_summary, \"recommendations\": recommendations}",
      "output": {
        "name": "quality_review_report",
        "typeName": "Record",
        "fields": [
          {"name": "review_summary", "typeName": "String"},
          {"name": "recommendations", "typeName": "List<String>"}
        ]
      }
    },
    {
      "kind": "primitive",
      "name": "generate_report",
      "capability": "execute_python",
      "inputBindings": [
        {"param": "merged_results", "source": "merge_results", "binding": "merged_results"},
        {"param": "quality_review", "source": "quality_review", "binding": "quality_review_report"}
      ],
      "code": "stats = merged_results[\"aggregated_stats\"]\nissues = merged_results[\"all_issues\"]\nreview = quality_review_report\nreport_lines = [\n    \"# Consolidated Quarterly Sales Report\",\n    \"## Aggregated Statistics\",\n    f\"- Total Sales: {stats['total_sales']:.2f}\",\n    f\"- Average Sales: {stats['average_sales']:.2f}\",\n    f\"- Min Sales: {stats['min_sales']:.2f}\",\n    f\"- Max Sales: {stats['max_sales']:.2f}\",\n    f\"- Total Rows: {stats['total_rows']}\",\n    f\"- Quarters Processed: {stats['quarters_processed']}\",\n    \"## Quality Review\",\n    f\"- {review['review_summary']}\",\n    \"### Recommendations\",\n]\nfor rec in review[\"recommendations\"]:\n    report_lines.append(f\"- {rec}\")\nreport_lines.append(\"## Evidence Log\")\nfor i, issue in enumerate(issues):\n    report_lines.append(f\"{i+1}. {issue}\")\nenv[\"final_report\"] = \"\\n\".join(report_lines)",
      "output": {
        "name": "final_report",
        "typeName": "String",
        "fields": []
      }
    }
  ],
  "dataFlow": [
    {"fromStep": "process_files", "toStep": "merge_results", "binding": "all_file_reports"},
    {"fromStep": "merge_results", "toStep": "quality_review", "binding": "merged_results"},
    {"fromStep": "merge_results", "toStep": "generate_report", "binding": "merged_results"},
    {"fromStep": "quality_review", "toStep": "generate_report", "binding": "quality_review_report"}
  ]
}
